#!/usr/bin/env bash
# Rebuild p3cat.wasm, regenerate testdata/p3cat.stdin, and re-take testdata/p3cat.reading and
# testdata/p3cat-empty.reading (#1234, #1264, ADR 0122).
#
# **Run deliberately and out of CI.** The committed p3cat.wasm, p3cat.stdin and the two readings ARE the
# artefacts; this script exists so they can be regenerated when a tool moves, not so anything on the test path
# invokes a Rust toolchain or wasmtime (p3sys/build.sh's shape: commit the oracle's reading, never depend on the
# oracle at test time).
#
# Offline: the crate has no dependencies, and cargo runs `--offline --locked` against the committed
# Cargo.lock, so a rebuild fetches nothing.
#
# ## Pitfalls already paid for
#
#   * `rustc +nightly` resolves to Homebrew's 1.99.1 on this machine, which has no wasm32-wasip3 target. The
#     nightly is named by its toolchain directory, and cargo is handed that rustc by RUSTC, not by PATH.
#   * The build runs in a scratch copy, never in the tree, so no target/ directory appears under testdata
#     and a warm cache from another tree cannot answer for this one.
#   * The guest reads a pipe-like stream in pieces, so one run is not a reading: RUNS runs (default 10) of each
#     stdin are taken, and the script fails unless every run's stdout, stderr and exit are byte-identical to
#     the first's.
#   * The stdin is generated, not hand-written: 310 lines of 67 bytes, 20770 bytes, which is two full 8 KiB
#     reads and a short third, so read_to_end sees partial progress before the end.
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../../../.." && pwd)
td="$repo/internal/component/testdata"
: "${NIGHTLY:=$HOME/.rustup/toolchains/nightly-aarch64-apple-darwin}"
: "${CARGO:=$NIGHTLY/bin/cargo}"
: "${RUSTC:=$NIGHTLY/bin/rustc}"
: "${WASM_TOOLS:=wasm-tools}"
# The pinned oracle that scripts/oracle-fetch.sh installs, never the wasmtime on PATH (50.0.1 on this machine).
# A worktree has no .oracle of its own, so the main checkout's is the fallback.
: "${WASMTIME:=$repo/.oracle/wasmtime-49.0.3/wasmtime}"
[ -x "$WASMTIME" ] || WASMTIME="$HOME/src/burroughs/.oracle/wasmtime-49.0.3/wasmtime"

for t in "$CARGO" "$RUSTC" "$WASMTIME"; do
	[ -x "$t" ] || { echo "build.sh: $t is not executable" >&2; exit 2; }
done

: "${EXPECT_RUSTC:=rustc 1.100.0-nightly}"
: "${EXPECT_WASM_TOOLS:=wasm-tools 1.258.0}"
: "${EXPECT_WASMTIME:=wasmtime 49.0.3}"
expect_version() { # expect_version <tool> <"name version">: the first two fields of `<tool> --version`
	got=$("$1" --version | awk 'NR == 1 {print $1, $2}')
	[ "$got" = "$2" ] || {
		echo "build.sh: $1 is '$got', and the committed artefacts were built and read with '$2'." >&2
		echo "          Rebuild and re-take on the new version, and move the expectation in the same commit." >&2
		exit 2
	}
}
expect_version "$RUSTC" "$EXPECT_RUSTC"
expect_version "$WASM_TOOLS" "$EXPECT_WASM_TOOLS"
expect_version "$WASMTIME" "$EXPECT_WASMTIME"

scratch_root=${TMPDIR:-/tmp}
[ -d "$HOME/.xtmp" ] && scratch_root="$HOME/.xtmp"
work=$(mktemp -d "$scratch_root/p3cat-build.XXXXXX")
trap 'rm -rf "$work"' EXIT
cp -R "$here/Cargo.toml" "$here/Cargo.lock" "$here/src" "$work/"

# The outputs are deleted before the build, so a failed build cannot leave the old artefact to be read.
rm -f "$here/p3cat.wasm" "$td/p3cat.stdin"
( cd "$work" && RUSTC="$RUSTC" CARGO_TARGET_DIR="$work/target" \
	"$CARGO" build --offline --locked --release --target wasm32-wasip3 )
cp "$work/target/wasm32-wasip3/release/p3cat.wasm" "$here/p3cat.wasm"
"$WASM_TOOLS" validate --features all "$here/p3cat.wasm"

awk 'BEGIN { for (i = 1; i <= 310; i++) printf "p3cat stdin line %04d: the quick brown fox jumps over the lazy dog\n", i }' \
	>"$td/p3cat.stdin"

: "${RUNS:=10}"
ends() { # ends <file>: "yes" if the file's last byte is a newline, else "no"
	[ -s "$1" ] && [ "$(tail -c 1 "$1" | od -An -c | tr -d ' ')" = '\n' ] && echo yes || echo no
}
prefix() { # prefix <name> <file>: each line of the file, newline-terminated or not, as "<name>: <line>"
	awk -v p="$1: " '{print p $0}' "$2"
}
# reading <stdin file> <its name in the reading> <reading file>: RUNS runs, compared, then the reading.
reading() {
	local in=$1 name=$2 out=$3 code c i
	"$WASMTIME" run "$here/p3cat.wasm" <"$in" >"$work/stdout" 2>"$work/stderr" && code=0 || code=$?
	for i in $(seq 2 "$RUNS"); do
		"$WASMTIME" run "$here/p3cat.wasm" <"$in" >"$work/stdout.$i" 2>"$work/stderr.$i" && c=0 || c=$?
		if [ "$c" != "$code" ] || ! cmp -s "$work/stdout" "$work/stdout.$i" || ! cmp -s "$work/stderr" "$work/stderr.$i"; then
			echo "build.sh: run $i on $name differs from run 1 (exit $c, want $code); a reading must be stable" >&2
			diff "$work/stdout" "$work/stdout.$i" >&2 || true
			exit 1
		fi
	done
	{
		echo "# Committed reading of internal/component/testdata/p3cat/p3cat.wasm (#1234, #1264; ADR 0122)."
		echo "# Regenerated by p3cat/build.sh; never hand-edited."
		echo "# Built:       p3cat/build.sh ($("$RUSTC" --version | awk '{print $1, $2}'), no dependencies, wasm32-wasip3)"
		echo "# Invocation:  wasmtime run p3cat.wasm <$name"
		echo "# stdin bytes: $(wc -c <"$in" | tr -d ' ')"
		echo "# Engine:      $("$WASMTIME" --version), $(uname -s | tr 'A-Z' 'a-z')/$(uname -m | sed 's/aarch64/arm64/')."
		echo "# Runs:        $RUNS of $RUNS byte-identical (stdout, stderr and exit)"
		echo "# exit:        $code"
		echo "# stdout ends with a newline: $(ends "$work/stdout")"
		echo "# stderr bytes: $(wc -c <"$work/stderr" | tr -d ' ')"
		echo "#"
		echo "# Each line below is one channel's line, prefixed by the channel's name."
		prefix stdout "$work/stdout"
		prefix stderr "$work/stderr"
	} >"$out"
	cat "$out"
}
reading "$td/p3cat.stdin" "p3cat.stdin" "$td/p3cat.reading"
reading /dev/null "/dev/null" "$td/p3cat-empty.reading"
shasum -a 256 "$here/p3cat.wasm" "$td/p3cat.stdin"
wc -c <"$here/p3cat.wasm"
